css:
/* From Uiverse.io by Li-Deheng - Tags: slider, pricing, card, price, range */
.__UIV_SCOPE__ .card-conteiner {
  cursor: default;
  --color-primary: #275efe;
  --color-headline: #3f4656;
  --color-text: #99a3ba;
}

.__UIV_SCOPE__ .card-content {
  width: 100%;
  max-width: 312px;
  padding: 36px 32px;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 1px 4px rgba(18, 22, 33, .12);
}

.__UIV_SCOPE__ .card-content .card-title {
  font-family: inherit;
  font-size: 32px;
  font-weight: 700;
  margin: 0 0 10px 0;
  color: var(--color-headline);
}

.__UIV_SCOPE__ .card-content .card-title span {
  font-weight: 500;
}

.__UIV_SCOPE__ .card-content .values div, .__UIV_SCOPE__ .card-content .current-range div {
  display: inline-block;
  vertical-align: top;
}

.__UIV_SCOPE__ .card-content .values {
  margin: 0;
  font-weight: 500;
  color: var(--color-primary);
}

.__UIV_SCOPE__ .card-content .values > div:first-child {
  margin-right: 2px;
}

.__UIV_SCOPE__ .card-content .values > div:last-child {
  margin-left: 2px;
}

.__UIV_SCOPE__ .card-content .current-range {
  display: block;
  color: var(--color-text);
  margin-top: 8px;
  font-size: 14px;
}

.__UIV_SCOPE__ .card-content .slider {
  display: flex;
  justify-content: space-between;
  margin-top: 20px;
  font-size: .6em;
  color: var(--color-text);
}

/* Range Slider */
.__UIV_SCOPE__ .input-ranges[type='range'] {
  width: 210px;
  height: 30px;
  overflow: hidden;
  outline: none;
}

.__UIV_SCOPE__ .input-ranges[type='range'],
.__UIV_SCOPE__ .input-ranges[type='range']::-webkit-slider-runnable-track,
.__UIV_SCOPE__ .input-ranges[type='range']::-webkit-slider-thumb {
  -webkit-appearance: none;
  background: none;
}

.__UIV_SCOPE__ .input-ranges[type='range']::-webkit-slider-runnable-track {
  width: 200px;
  height: 1px;
  background: var(--color-headline);
}

.__UIV_SCOPE__ .input-ranges[type='range']:nth-child(2)::-webkit-slider-runnable-track {
  background: none;
}

.__UIV_SCOPE__ .input-ranges[type='range']::-webkit-slider-thumb {
  position: relative;
  height: 15px;
  width: 15px;
  margin-top: -7px;
  background: #fff;
  border: 1px solid var(--color-headline);
  border-radius: 25px;
  cursor: pointer;
  z-index: 1;
  transition: .5s;
  -webkit-transition: .5s;
  -moz-transition: .5s;
  -ms-transition: .5s;
  -o-transition: .5s;
}

.__UIV_SCOPE__ .input-ranges[type='range']::-webkit-slider-thumb:hover {
  background: #eaefff;
  border: 1px solid var(--color-primary);
  outline: .5px solid var(--color-primary);
}

.__UIV_SCOPE__ .input-ranges[type='range']::-webkit-slider-thumb:active {
  cursor: grabbing;
}

.__UIV_SCOPE__ .input-ranges[type='range']:nth-child(1)::-webkit-slider-thumb {
  z-index: 2;
}

.__UIV_SCOPE__ .rangeslider {
  font-family: sans-serif;
  font-size: 14px;
  position: relative;
  height: 20px;
  width: 210px;
  display: inline-block;
  margin-top: -5px;
}

.__UIV_SCOPE__ .rangeslider input {
  position: absolute;
}

.__UIV_SCOPE__ .rangeslider span {
  position: absolute;
  margin-top: 20px;
  left: 0;
}

.__UIV_SCOPE__ .rangeslider .right {
  position: relative;
  float: right;
  margin-right: -5px;
}
